import { Component, input, Input, SimpleChanges } from '@angular/core';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { AdventureTimeService } from '../../Shared/services/adventure-time.service';
import { filesearchattributesdata } from '../../Shared/Models/FileAdditionalInfo';
import { HttpClient } from '@angular/common/http';

@Component({
    selector: 'my-video',
    templateUrl: './videoplayer.component.html',
    styleUrls: ['./videoplayer.component.css']
})
export class VideoplayerComponent {
    name = 'Angular 6';
    safeSrc: SafeResourceUrl;
    safeSrc2: SafeResourceUrl[] = [];
    videoids: WeatherForecast1[] = [];
    @Input() searchword: string = "";
    @Input() type: string = "";
    @Input() landing: boolean = false;
    fileAdditonalData!: filesearchattributesdata;
    keywords: string = "";
    items: Array<string>;
    //searchword: string = "";
    data: any[] = [];

    constructor(private sanitizer: DomSanitizer, 
        private atService: AdventureTimeService
    , private _http: HttpClient ) {
        this.safeSrc = this.sanitizer.bypassSecurityTrustResourceUrl("https://www.youtube.com/embed/c9F5kMUfFKk");

        this.items = this.atService.getVideodata(this.searchword);
        // this.safeSrc2.push(this.sanitizer.bypassSecurityTrustResourceUrl("https://www.youtube.com/embed/c9F5kMUfFKk"));

    }
    ngOnChanges(changes: SimpleChanges) {

        //console.log("**** searchword changed to " + this.type);

        if (this.type != 'video' && this.type != 'advancedsearch') return;
        if (this.type === 'video') {
            this.atService.getvideodata1(this.searchword)
                .subscribe((res: any) => {
                    this.data = res;
                    this.data.forEach(x => console.log(x.name));
                    if(this.landing) {  
                        this.safeSrc = this.safeSrc2.push(this.sanitizer.bypassSecurityTrustResourceUrl("https://www.youtube.com/embed/" + this.data[0].name));
                    }
                    else
                    this.data.forEach(x => this.safeSrc2.push(this.sanitizer.bypassSecurityTrustResourceUrl("https://www.youtube.com/embed/" + x.name)));

                }, (err: any) => {
                    console.log(err);
                });
        }
        else if (this.type === 'advancedsearch') {
            this.safeSrc2 = [];
            // console.log(" *******request for video by cateory"+ this.searchword);
            this.atService.GetVidoesByCategory(this.searchword).subscribe((res: any) => {
                this.data = res;
                this.data.forEach(x => {
                    if (x.fileName != null && x.fileName.includes("youtube")
                    ) {
                        console.log("**** video data " + x.fileName);



                        // if(x.filename != null && x.fileName.includes("youtube")) 
                        this.safeSrc2.push(this.sanitizer.bypassSecurityTrustResourceUrl(x.fileName));
                        // console.log("**** video data " + x.fileName);
                    }
                })
            }, (err: any) => {
                console.log(err);
            });
        }
        console.log("**** SEARCH data " + JSON.stringify(this.safeSrc2));
    }
    UpdateKeywords(event: any) {
        this.keywords = event.target.value;
        console.log("keywords updated" + this.keywords);
    }
    UpdaeKeyWrods(event: any) {
        // console.log("keywords"+ this.keywords);
        // console.log("filename: "+JSON.stringify(event));
        let filename = event.changingThisBreaksApplicationSecurity;
        console.log(filename);
        this.fileAdditonalData = {
            username: "Anonymous",
            fileName: filename,
            keywords: this.keywords.split(','),
            videourls: this.data.map(x => "https://www.youtube.com/embed/" + x.name),
            fileCategory: this.searchword,
            summary: "NA"


        };
        this.atService.updateMongoDBFileInfo(this.fileAdditonalData);
    }   
    UpdateLandingPage(event: any, e: any) {
        let filename = event.changingThisBreaksApplicationSecurity;
        let url = 'https://talashvideo.azurewebsites.net/PromoteToLandingPage_post?input=' + filename;
        let body = {
            fileName: filename,
        }
        this._http.post(url, body).subscribe((res: any) => {
            console.log("Promote to landing page response: " + JSON.stringify(res));
        }, (err: any) => {
            console.log("Promote to landing page error: " + JSON.stringify(err));
        }   );
        
    }
}
interface WeatherForecast1 {
    name: string;

}
<!-- Grid row -->
<!--Carousel Wrapper-->
<div style="height: 200px;" id="video-carousel-example" class="carousel slide carousel-fade" data-ride="carousel">
    <!--Indicators-->
    <ol class="carousel-indicators">
        <li data-target="#video-carousel-example" data-slide-to="0" class="active"></li>
        <li data-target="#video-carousel-example" data-slide-to="1"></li>
        <li data-target="#video-carousel-example" data-slide-to="2"></li>
    </ol>
<p *ngFor="let ids of videoids; last as isLast">test{{ids}}
</p>
<table style="margin:10px;border:0px;text-decoration-thickness: 2;background-color: rgb(237, 239, 239);"> 
    

<p *ngFor="let ss of safeSrc2; last as isLast">
<tr>
        <td>
 <div style="padding: 50px;">

    <iframe  [src]="ss" width="560" height="250" frameborder="0" webkitallowfullscreen mozallowfullscreen
            allowfullscreen> </iframe>
            </div>
            
        </td>   
        <td style="vertical-align: middle;font-size: small    ;color:brick  ;">
            <span><div style="border:0px">    Download  <a href="https://www.socialplug.io/free-tools/youtube-video-downloader">You tube downloder</a></div>


                <div style="border:0px">  Share : facebook, twitter , linked in</div>


                </span>
            Add Key words : <input  (keyup)="UpdateKeywords($event)" type="text" /><button (click)="UpdaeKeyWrods(ss)">Update</button>
           <br><br>
           <div *if="!landing">   
           Promote to Landing page <input type="checkbox" (change)="UpdateLandingPage(ss,$event)"/>
           </div>  
           <hr>
            <details>
                <summary>How to: creating Tags</summary>
            <div style="padding:30px;background-color:rgb(240, 236, 243);border-width: 0ch">  <br> <h4>Creating tags: </h4>
             Step 1: add tags using above keywords edit box.<br>
              Steps 2: above tabgs can be used in Search in right hand panel.
              Step 3: similar tag videos can be created as playlist and can be pushed to youtube
            <br>If any help needed We can add more videos for any requested topic. It will cost 20$ for 300 videos.
          please contact sales</div>
          </details>
        </td>
   
</tr>
